INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-communication-10','COMMUNICATION-10','Tiếng Trung giao tiếp · Đề 10','communication','Tiếng Trung giao tiếp',60,'published',1,'Đề luyện tiếng trung giao tiếp số 10 do Nhà Hán Ngữ biên soạn phục vụ tự học và tự đánh giá.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-communication-10-q01','seed-communication-10',1,'single_choice','A: 对不起，我迟到了。 Chọn câu đáp phù hợp nhất.','Tình huống: Xin lỗi vì đến muộn. Câu trả lời phù hợp là “B: 没关系，我们刚开始。” vì trực tiếp đáp lại ý của người nói và giữ mạch hội thoại tự nhiên.',NULL,NULL,0,1,'',datetime('now')),
('seed-communication-10-q02','seed-communication-10',2,'single_choice','A: 你为什么学习中文？ Chọn câu đáp phù hợp nhất.','Tình huống: Nói lý do học tiếng Trung. Câu trả lời phù hợp là “B: 因为我对语言和文化很感兴趣。” vì trực tiếp đáp lại ý của người nói và giữ mạch hội thoại tự nhiên.',NULL,NULL,0,1,'',datetime('now')),
('seed-communication-10-q03','seed-communication-10',3,'single_choice','A: 可以帮我看一下这句话吗？ Chọn câu đáp phù hợp nhất.','Tình huống: Nhờ giúp xem câu. Câu trả lời phù hợp là “B: 当然可以，你哪里不明白？” vì trực tiếp đáp lại ý của người nói và giữ mạch hội thoại tự nhiên.',NULL,NULL,0,1,'',datetime('now')),
('seed-communication-10-q04','seed-communication-10',4,'single_choice','A: 明天下午三点见，可以吗？ Chọn câu đáp phù hợp nhất.','Tình huống: Xác nhận thời gian gặp. Câu trả lời phù hợp là “B: 可以，到时候见。” vì trực tiếp đáp lại ý của người nói và giữ mạch hội thoại tự nhiên.',NULL,NULL,0,1,'',datetime('now')),
('seed-communication-10-q05','seed-communication-10',5,'single_choice','A: 你想喝茶还是咖啡？ Chọn câu đáp phù hợp nhất.','Tình huống: Chọn đồ uống. Câu trả lời phù hợp là “B: 我想喝茶，谢谢。” vì trực tiếp đáp lại ý của người nói và giữ mạch hội thoại tự nhiên.',NULL,NULL,0,1,'',datetime('now')),
('seed-communication-10-q06','seed-communication-10',6,'single_choice','A: 你好，请问图书馆怎么走？ Chọn câu đáp phù hợp nhất.','Tình huống: Hỏi đường đến thư viện. Câu trả lời phù hợp là “B: 一直往前走，在右边。” vì trực tiếp đáp lại ý của người nói và giữ mạch hội thoại tự nhiên.',NULL,NULL,0,1,'',datetime('now')),
('seed-communication-10-q07','seed-communication-10',7,'single_choice','A: 你周末有时间吗？ Chọn câu đáp phù hợp nhất.','Tình huống: Hẹn cùng ôn bài. Câu trả lời phù hợp là “B: 有，我们可以一起复习。” vì trực tiếp đáp lại ý của người nói và giữ mạch hội thoại tự nhiên.',NULL,NULL,0,1,'',datetime('now')),
('seed-communication-10-q08','seed-communication-10',8,'single_choice','A: 这个菜怎么样？ Chọn câu đáp phù hợp nhất.','Tình huống: Nhận xét món ăn. Câu trả lời phù hợp là “B: 我觉得很好吃，就是有点儿辣。” vì trực tiếp đáp lại ý của người nói và giữ mạch hội thoại tự nhiên.',NULL,NULL,0,1,'',datetime('now')),
('seed-communication-10-q09','seed-communication-10',9,'single_choice','A: 对不起，我迟到了。 Chọn câu đáp phù hợp nhất.','Tình huống: Xin lỗi vì đến muộn. Câu trả lời phù hợp là “B: 没关系，我们刚开始。” vì trực tiếp đáp lại ý của người nói và giữ mạch hội thoại tự nhiên.',NULL,NULL,0,1,'',datetime('now')),
